// Generated by ipadport. Serves the bundled web app from app://local/ so that ES modules,
// fetch(), relative and absolute paths, and single-page-app routes work like they do on desktop.

import Foundation
import UniformTypeIdentifiers
import WebKit

final class AppSchemeHandler: NSObject, WKURLSchemeHandler {
    private static let mimeTypes: [String: String] = [
        "html": "text/html", "htm": "text/html", "js": "text/javascript", "mjs": "text/javascript",
        "cjs": "text/javascript", "css": "text/css", "json": "application/json", "map": "application/json",
        "wasm": "application/wasm", "svg": "image/svg+xml", "png": "image/png", "jpg": "image/jpeg",
        "jpeg": "image/jpeg", "gif": "image/gif", "webp": "image/webp", "ico": "image/x-icon",
        "woff": "font/woff", "woff2": "font/woff2", "ttf": "font/ttf", "otf": "font/otf",
        "mp3": "audio/mpeg", "mp4": "video/mp4", "webm": "video/webm", "txt": "text/plain",
        "xml": "application/xml", "pdf": "application/pdf",
    ]

    func webView(_ webView: WKWebView, start urlSchemeTask: WKURLSchemeTask) {
        guard let url = urlSchemeTask.request.url else {
            urlSchemeTask.didFailWithError(URLError(.badURL))
            return
        }
        let root = AppConfig.webRoot.standardizedFileURL
        var relative = url.path
        while relative.hasPrefix("/") { relative.removeFirst() }
        if relative.isEmpty { relative = AppConfig.entry }

        var fileURL = root.appendingPathComponent(relative).standardizedFileURL
        guard fileURL.path == root.path || fileURL.path.hasPrefix(root.path + "/") else {
            respond(urlSchemeTask, url: url, status: 403, data: Data("Forbidden".utf8), mime: "text/plain")
            return
        }

        var isDirectory: ObjCBool = false
        if FileManager.default.fileExists(atPath: fileURL.path, isDirectory: &isDirectory), isDirectory.boolValue {
            fileURL.appendPathComponent("index.html")
        }
        if !FileManager.default.fileExists(atPath: fileURL.path) && fileURL.pathExtension.isEmpty {
            // Single-page-app fallback: unknown routes without a file extension load the entry page.
            fileURL = root.appendingPathComponent(AppConfig.entry)
        }

        guard let data = try? Data(contentsOf: fileURL) else {
            respond(urlSchemeTask, url: url, status: 404, data: Data("Not found: \(url.path)".utf8), mime: "text/plain")
            return
        }
        let ext = fileURL.pathExtension.lowercased()
        let mime = Self.mimeTypes[ext] ?? UTType(filenameExtension: ext)?.preferredMIMEType ?? "application/octet-stream"
        respond(urlSchemeTask, url: url, status: 200, data: data, mime: mime)
    }

    func webView(_ webView: WKWebView, stop urlSchemeTask: WKURLSchemeTask) {}

    private func respond(_ task: WKURLSchemeTask, url: URL, status: Int, data: Data, mime: String) {
        var headers = [
            "Content-Type": mime,
            "Content-Length": String(data.count),
            "Access-Control-Allow-Origin": "*",
            "Cache-Control": "no-cache",
        ]
        if mime.hasPrefix("text/") || mime == "application/json" {
            headers["Content-Type"] = mime + "; charset=utf-8"
        }
        let response = HTTPURLResponse(url: url, statusCode: status, httpVersion: "HTTP/1.1", headerFields: headers)!
        task.didReceive(response)
        task.didReceive(data)
        task.didFinish()
    }
}
